const output = $input.item.json.output || "";
let intent = "faq";
let cleanMessage = output;

// Procura pela tag gerada pelo Agente
const regex = /\[INTENT:\s*(faq|produto|orcamento|pedido|followup|humano)\]/i;
const match = output.match(regex);

if (match) {
  intent = match[1].toLowerCase();
  // Remove a tag do texto para não aparecer para o cliente
  cleanMessage = output.replace(regex, "").trim();
}

return {
  intent: intent,
  cleanMessage: cleanMessage
};
